import hashlib
import time
import ssl
import socket
from enum import Enum
from collections import deque
from urllib.parse import urlparse
import unicodedata


class CircuitState(Enum):
    CLOSED = "closed"
    OPEN = "open"
    HALF_OPEN = "half_open"


class CircuitBreaker:
    def __init__(self, failure_threshold=5, recovery_timeout=30):
        self.failure_threshold = failure_threshold
        self.recovery_timeout = recovery_timeout
        self.state = CircuitState.CLOSED
        self.failure_count = 0
        self.last_failure_time = 0
        self.request_log = deque(maxlen=100)

    def record_success(self):
        self.failure_count = 0
        if self.state == CircuitState.HALF_OPEN:
            self.state = CircuitState.CLOSED

    def record_failure(self):
        self.failure_count += 1
        self.last_failure_time = time.time()
        if self.failure_count >= self.failure_threshold:
            self.state = CircuitState.OPEN

    def can_execute(self):
        if self.state == CircuitState.CLOSED:
            return True
        if self.state == CircuitState.OPEN:
            if time.time() - self.last_failure_time > self.recovery_timeout:
                self.state = CircuitState.HALF_OPEN
                return True
            return False
        return True  # HALF_OPEN allows one request


class FirmwareUpdateClient:
    TRUSTED_HOSTS = [
        "firmware.iot-devices.com",
        "updates.iot-devices.com",
        "cdn.iot-devices.com",
    ]

    def __init__(self):
        self.circuit_breaker = CircuitBreaker(failure_threshold=3, recovery_timeout=60)
        self.current_version = "1.0.0"
        self._session_nonce = hashlib.sha256(str(time.time()).encode()).hexdigest()[:16]

    def _normalize_hostname(self, hostname):
        """Normalize hostname for consistent comparison."""
        # Apply NFKC normalization as recommended for domain names (RFC 5892)
        normalized = unicodedata.normalize('NFKC', hostname)
        # Reject any non-ASCII characters after normalization
        try:
            normalized.encode('ascii')
        except UnicodeEncodeError:
            return None
        return normalized.lower().strip()

    def _is_trusted_host(self, url):
        """Verify the update URL points to a trusted host."""
        try:
            parsed = urlparse(url)
            hostname = parsed.hostname
            if hostname is None:
                return False
            normalized_host = self._normalize_hostname(hostname)
            if normalized_host is None:
                return False
            for trusted in self.TRUSTED_HOSTS:
                trusted_normalized = self._normalize_hostname(trusted)
                if trusted_normalized is None:
                    continue
                if normalized_host == trusted_normalized:
                    return True
            return False
        except Exception:
            return False

    def _verify_certificate_chain(self, hostname, port=443):
        """Verify TLS certificate for the given hostname."""
        ctx = ssl.create_default_context()
        ctx.check_hostname = True
        ctx.verify_mode = ssl.CERT_REQUIRED
        try:
            with socket.create_connection((hostname, port), timeout=10) as sock:
                with ctx.wrap_socket(sock, server_hostname=hostname) as ssock:
                    cert = ssock.getpeercert()
                    return cert is not None
        except (ssl.SSLError, socket.error, OSError):
            return False

    @staticmethod
    def _has_control_chars(value):
        """Detect CR/LF or other control characters that could enable request injection."""
        if value is None:
            return True
        for ch in value:
            if ch in ('\r', '\n') or ord(ch) < 0x20 or ord(ch) == 0x7f:
                return True
        return False

    def _download_firmware(self, url):
        """Download firmware binary from URL with circuit breaker protection."""
        if not self.circuit_breaker.can_execute():
            raise ConnectionError("Circuit breaker is OPEN - update server unreachable")

        parsed = urlparse(url)
        hostname = parsed.hostname
        path = parsed.path or "/"
        if parsed.query:
            path = f"{path}?{parsed.query}"

        # Reject any component that could inject CRLF into the raw HTTP request,
        # preventing HTTP request/header injection and request smuggling.
        if self._has_control_chars(hostname) or self._has_control_chars(path):
            self.circuit_breaker.record_failure()
            raise ConnectionError("Download failed: invalid characters in request target")

        try:
            ctx = ssl.create_default_context()
            with socket.create_connection((hostname, 443), timeout=15) as sock:
                with ctx.wrap_socket(sock, server_hostname=hostname) as ssock:
                    request = f"GET {path} HTTP/1.1\r
Host: {hostname}\r
Connection: close\r
\r
"
                    ssock.sendall(request.encode())
                    response = b""
                    while True:
                        chunk = ssock.recv(4096)
                        if not chunk:
                            break
                        response += chunk
            self.circuit_breaker.record_success()
            return response
        except (socket.error, ssl.SSLError, OSError) as e:
            self.circuit_breaker.record_failure()
            raise ConnectionError(f"Download failed: {e}")

    def check_and_apply_update(self, update_url):
        """Main entry point: check if URL is trusted, download and apply firmware."""
        # Step 1: Validate the source
        if not self._is_trusted_host(update_url):
            return {"status": "rejected", "reason": "untrusted host"}

        # Step 2: Parse and verify
        parsed = urlparse(update_url)
        hostname = parsed.hostname

        # Step 3: Verify certificate (with circuit breaker)
        if not self.circuit_breaker.can_execute():
            return {"status": "deferred", "reason": "circuit breaker open"}

        # Step 4: Download the firmware
        try:
            firmware_data = self._download_firmware(update_url)
        except ConnectionError as e:
            return {"status": "failed", "reason": str(e)}

        # Step 5: Verify firmware integrity
        if not self._verify_firmware_signature(firmware_data):
            return {"status": "rejected", "reason": "invalid signature"}

        return {"status": "success", "version": "updated"}

    def _verify_firmware_signature(self, data):
        """Stub: In production, verify Ed25519 signature on firmware blob."""
        if data and len(data) > 256:
            return True
        return False


def handle_ota_request(payload):
    """Handle incoming OTA update request from cloud management platform."""
    client = FirmwareUpdateClient()
    update_url = payload.get("url", "")
    if not update_url:
        return {"error": "no URL provided"}
    result = client.check_and_apply_update(update_url)
    return result
